let seasonData=null,seasonTab='plan';
const seasonLabels={calendar:'Событие',waitlist:'Очередь',move:'Смена участка',equipment:'Оборудование',equipment_rent:'Аренда оборудования',weather:'Погода',sensor:'Измерение',watering:'Проверка полива',photo_issue:'Проблема на фото',photos:'До и после',rework:'Переделка',substitute:'Замена материала',preorder:'Предзаказ',crate:'Возврат тары'};
const seasonState={saved:'Записано / ожидает решения',reviewed:'Рассмотрено',accepted:'Согласовано владельцем',rejected:'Отклонено владельцем',done:'Выполнено',cancelled:'Отменено',returned:'Возврат тары подтверждён',refunded:'Возврат залога подтверждён'};
async function loadSeason(){if(!account)return;try{seasonData=await api('season');await loadLife();render()}catch(e){toast(e.message)}}
async function seasonAction(action,b){await api('season-'+action,b);await refreshCloud();await loadSeason()}
function seasonPlotOptions(){return cloud?.plots.filter(p=>p.mine||account?.role==='admin').map(p=>`<option value="${p.id}">№${p.id} · ${esc(p.name)}</option>`).join('')||''}
const sf=(name,label,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" ${extra}></label>`;
const sp=()=>`<label>Грядка<select name="plot" required>${seasonPlotOptions()}</select></label>`;
const se=(label,fn)=>`<button class="btn light" onclick="${fn}">${label}</button>`;
function seasonForm(title,fields,handler){formAsync(title,fields+'<button class="btn">Сохранить</button>',handler)}
function seasonEntry(kind){let fields=kind==='waitlist'?sf('plot','Номер желаемой грядки','number','min="1" max="50" required'):sp();fields+=sf('title','Название','text','required maxlength="120"');const extras={calendar:sf('at','Дата события','datetime-local','required'),move:sf('target','Желаемый участок','number','min="1" max="50" required'),equipment:sf('serial','Номер / модель')+sf('ownership','Собственник')+sf('installed','Дата установки','date')+sf('maintenance','Следующее обслуживание','date'),equipment_rent:sf('until','До какой даты нужно','date','required'),weather:sf('at','Действует до','datetime-local','required')+sf('source','Источник прогноза','url','required'),sensor:sf('value','Измерение','number','step="any" required')+sf('unit','Единица и тип датчика','text','required')+sf('at','Время измерения','datetime-local','required'),watering:sf('value','Объём воды','number','min="0" step="any" required')+sf('unit','Единица','text','value="л" required')+sf('at','Фактическое время','datetime-local','required')+sf('order','ID работы, если есть'),photo_issue:sf('url','HTTPS-ссылка на фото','url','required')+sf('x','Положение отметки по горизонтали, %','number','min="0" max="100" value="50" required')+sf('y','По вертикали, %','number','min="0" max="100" value="50" required'),photos:sf('before','Фото до · HTTPS','url','required')+sf('after','Фото после · HTTPS','url','required')+sf('order','ID работы, если есть'),rework:sf('order','ID исходной работы','text','required'),substitute:sf('order','ID работы','text','required')+sf('original','Исходный материал')+sf('replacement','Предложенная замена')+sf('difference','Разница цены, ₽','number','step="0.01" required'),preorder:sf('crop','Культура','text','required')+sf('quantity','Желаемая масса, кг','number','min="0.1" step="0.1" required')+sf('until','Желаемый срок','date','required'),crate:sf('deposit','Учтённый залог, ₽','number','min="0" step="0.01" required')+sf('reference','Номер тары / доставки')};fields+=extras[kind]||'';fields+='<label>Подробности<textarea name="notes" maxlength="2000" required></textarea></label>';if(kind==='crate')fields+='<p class="note">Учёт фактически внесённого залога. Эта запись не списывает и не переводит деньги.</p>';if(kind==='preorder')fields+='<p class="note">Предварительная заявка без оплаты и гарантии урожая. Вес и цена согласуются после сбора.</p>';if(kind==='move')fields+='<p class="note">Это согласование переезда. Растения, оборудование и владение участком автоматически не переносятся.</p>';seasonForm(seasonLabels[kind],fields,async f=>{const d=Object.fromEntries(f);delete d.title;delete d.plot;for(const k of ['value','x','y','quantity','difference'])if(k in d)d[k]=Number(d[k]);if('deposit'in d)d.deposit=Math.round(Number(d.deposit)*100);if(d.at)d.at=new Date(d.at).toISOString();await seasonAction('entry',{kind,plot:Number(f.get('plot')),title:f.get('title'),data:d})})}
function seasonTransition(id,status){seasonForm('Подтвердить изменение',sf('comment','Комментарий','text','required minlength="3"')+(status==='refunded'?'<p>Подтвердите только фактический возврат залога вне платформы. Автоматического перевода денег не будет.</p>':''),async f=>seasonAction('transition',{id,status,comment:f.get('comment')}))}
function entryCard(e){const d=e.data;let actions='';if(e.owner_id===account.id&&e.kind==='substitute'&&e.status==='saved')actions+=se('Согласовать',`seasonTransition('${e.id}','accepted')`)+se('Отклонить',`seasonTransition('${e.id}','rejected')`);if(e.owner_id===account.id&&['saved','reviewed'].includes(e.status))actions+=se('Отменить',`seasonTransition('${e.id}','cancelled')`);if(account.role==='admin'){if(e.status==='saved'&&e.kind!=='substitute')actions+=se(e.kind==='crate'?'Тара возвращена':'Рассмотреть',`seasonTransition('${e.id}','${e.kind==='crate'?'returned':'reviewed'}')`);if(['reviewed','accepted'].includes(e.status))actions+=se('Подтвердить выполнение',`seasonTransition('${e.id}','done')`);if(e.kind==='crate'&&e.status==='returned')actions+=se('Залог фактически возвращён',`seasonTransition('${e.id}','refunded')`)}const stale=e.kind==='sensor'&&Date.now()-Date.parse(d.at)>60*60*1000;return `<article class="panel"><small>${seasonLabels[e.kind]} · №${e.plot_id||'—'}</small><h3>${esc(e.title)}</h3><span class="pill">${seasonState[e.status]}</span>${stale?'<p class="harvest-alert">Измерение старше часа · не текущие показания</p>':''}<dl>${Object.entries(d).filter(([k])=>!['url','before','after'].includes(k)).map(([k,v])=>`<dt>${esc(({notes:'Подробности',at:'Время',value:'Значение',unit:'Единица',serial:'Номер',ownership:'Владелец',installed:'Установлено',maintenance:'Обслужить',order:'Работа',original:'Было',replacement:'Замена',difference:'Разница цены, ₽',deposit:'Залог, коп.',reference:'Номер тары',until:'До',crop:'Культура',quantity:'Кг',target:'Участок',source:'Источник',x:'X, %',y:'Y, %'})[k]||k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${e.kind==='photo_issue'?`<div class="marked-photo"><img src="${esc(d.url)}" alt="Фото проблемы" loading="lazy" referrerpolicy="no-referrer"><span style="left:${Number(d.x)}%;top:${Number(d.y)}%">⊕</span></div>`:''}${e.kind==='photos'?`<div class="photo-pair"><figure><img src="${esc(d.before)}" alt="До работы" loading="lazy" referrerpolicy="no-referrer"><figcaption>До</figcaption></figure><figure><img src="${esc(d.after)}" alt="После работы" loading="lazy" referrerpolicy="no-referrer"><figcaption>После</figcaption></figure></div>`:''}<div class="event">${(seasonData.events||[]).filter(v=>v.entry_id===e.id).map(v=>`<p>${fmt(v.created_at)} · ${esc(v.data.comment||'')}</p>`).join('')}</div><div class="actions">${actions}</div></article>`}
function seasonRenew(){seasonForm('Продлить демоаренду',`<label>Грядка<select name="plot">${myPlots().map(p=>`<option value="${p.id}">№${p.id} · ${money(p.rental_monthly_kopecks)} / месяц</option>`).join('')}</select></label>`+sf('months','Добавить месяцев','number','min="1" max="12" value="1" required')+'<p>Итого = указанный месячный тариф × количество месяцев. Списание с демобаланса, автоматического продления нет.</p>',async f=>seasonAction('renew',{plot:Number(f.get('plot')),months:Number(f.get('months')),key:crypto.randomUUID()}))}
function seasonGroup(){seasonForm('Объединить управление грядками',sf('name','Название огорода','text','required')+myPlots().map(p=>`<label><input type="checkbox" name="plots" value="${p.id}">№${p.id} · ${esc(p.name)}</label>`).join('')+'<p>Это группа ваших участков в интерфейсе. Физическое соседство подтверждает ферма; номера сами по себе его не гарантируют.</p>',async f=>seasonAction('group',{name:f.get('name'),plots:f.getAll('plots').map(Number)}))}
function cycleForm(previous){const cy=seasonData.cycles.find(c=>c.id===previous);seasonForm(cy?'Следующий цикл':'Новый цикл посадки',sp()+`<label>Зона<select name="zone"><option value="">Вся грядка</option>${(lifeData?.zones||[]).map(z=>`<option value="${z.id}">№${z.plot_id} · ${esc(z.name)}</option>`).join('')}</select></label>`+sf('crop','Культура','text','required')+sf('family','Семейство','text','required')+sf('start','Плановая / фактическая дата посадки','date','required')+sf('from','Ожидаемый сбор с','date')+sf('to','По','date')+sf('conditions','Условия: грунт, укрытие, полив','text','required')+'<p>Прогноз владельца предварительный. Управляющий подтверждает его по наблюдениям. Повторное семейство на участке — повод проверить севооборот, а не автоматический запрет.</p>',async f=>seasonAction('cycle',{...Object.fromEntries(f),plot:Number(f.get('plot'))}));if(cy)document.querySelector('#fields select[name=plot]').value=String(cy.plot_id)}
function cycleUpdate(id){seasonForm('Подтвердить прогноз / завершение',sf('from','Сбор с','date')+sf('to','Сбор по','date')+sf('end','Фактическое завершение цикла · оставьте пустым, если растёт','date'),async f=>seasonAction('cycle-update',{id,...Object.fromEntries(f)}))}
function partialHarvest(cycle){const key=crypto.randomUUID();seasonForm('Частичный сбор',sf('kg','Собрано, кг','number','min="0.001" step="0.001" required')+'<p>Цикл останется открытым. Новая партия потребует приёмки и назначения срока хранения.</p>',async f=>seasonAction('partial',{cycle,key,grams:Math.round(Number(f.get('kg'))*1000)}))}
function supplyForm(){seasonForm('Семена и материалы',sf('name','Название','text','required')+sf('unit','Единица: шт., г, мл…','text','required')+sf('quantity','Остаток','number','min="0" step="any" required')+sf('expires','Годен до','date'),async f=>seasonAction('supply',{...Object.fromEntries(f),quantity:Number(f.get('quantity'))}))}
function consumeSupply(id){const key=crypto.randomUUID();seasonForm('Учесть расход',sp()+sf('quantity','Израсходовано в единицах материала','number','min="0.001" step="any" required')+sf('reason','Основание / выполненная работа','text','required'),async f=>seasonAction('consume',{id,key,plot:Number(f.get('plot')),quantity:Number(f.get('quantity')),reason:f.get('reason')}))}
function customerVerdict(id,verdict){seasonForm(verdict==='accepted'?'Принять результат':'Замечание к работе',sf('comment','Комментарий','text',verdict==='issue'?'required minlength="10"':''),async f=>seasonAction('verdict',{id,verdict,comment:f.get('comment')}))}
function discountListing(id){seasonForm('Уценить свежий урожай',sf('price','Новая цена за весь лот, ₽','number','min="1" step="0.01" required'),async f=>seasonAction('discount',{id,price:Math.round(Number(f.get('price'))*100)}))}
function packagingForm(id){seasonForm('Упаковка корзины','<label>Вариант<select name="packaging"><option value="standard">Обычная</option><option value="returnable">Возвратная тара</option><option value="gift">Подарочная</option></select></label><p>Доступность и доплату согласует ферма перед подтверждением доставки.</p>',async f=>seasonAction('packaging',{id,packaging:f.get('packaging')}))}
function mergeDeliveries(){const ds=(lifeData?.deliveries||[]).filter(d=>d.user_id===account.id&&d.status==='requested');seasonForm('Объединить доставки',ds.map(d=>`<label><input type="checkbox" name="ids" value="${d.id}">${esc(d.recipient)} · ${esc(d.address)} · ${fmt(d.created_at)}</label>`).join('')+'<p>Только новые корзины с одинаковыми получателем, адресом, контактом и упаковкой. Купленные в демомаркете продукты поступают в ваши партии и могут попасть в общую корзину.</p>',async f=>seasonAction('merge-deliveries',{ids:f.getAll('ids')}))}
function cropRuleForm(){seasonForm('Агрономическая карточка для этой фермы',sf('crop','Культура','text','required')+sf('family','Семейство','text','required')+sf('from','Первый месяц посадки: 1–12','number','min="1" max="12" required')+sf('to','Последний месяц: 1–12','number','min="1" max="12" required')+sf('environment','Условия: открытый грунт / теплица…','text','required')+sf('days','Ориентир дней до сбора','number','min="1" required')+sf('area','Площадь на растение, м²','number','min="0.01" step="0.01" required')+sf('water','Группа условий полива','text','required')+sf('notes','Источник и пояснения','text','required'),async f=>{const b=Object.fromEntries(f);for(const k of ['from','to','days','area'])b[k]=Number(b[k]);await seasonAction('rule',b)})}
function cropAdvisor(){const f=document.getElementById('crop-advisor');if(!f)return;const month=Number(f.querySelector('[name=month]').value),plot=cloud.plots.find(p=>p.id===Number(f.querySelector('[name=plot]').value)),rules=seasonData.rules.filter(r=>r.month_from<=r.month_to?month>=r.month_from&&month<=r.month_to:month>=r.month_from||month<=r.month_to),out=document.getElementById('crop-advice');out.innerHTML=rules.map(r=>{const history=seasonData.cycles.some(c=>c.plot_id===plot?.id&&c.family===r.family);return `<div class="event"><b>${esc(r.crop)}</b><p>${esc(r.environment)} · ~${r.days_to_harvest} дней · до ${Math.floor((plot?.size||0)/Number(r.spacing_m2))} растений по норме карточки</p><p>${history?'На участке уже было это семейство — проверьте севооборот.':''}</p><small>${esc(r.notes)}</small></div>`}).join('')||'Для выбранного месяца управляющий ещё не утвердил культуры.'}
function compatibilityCheck(){const selected=[...document.querySelectorAll('[name=compare]:checked')].map(x=>seasonData.rules.find(r=>r.id===x.value));document.getElementById('compatibility-result').textContent=selected.length<2?'Выберите минимум две культуры.':new Set(selected.map(r=>r.environment)).size>1||new Set(selected.map(r=>r.water_group)).size>1?'Условия выращивания или группы полива различаются. Нужны отдельные зоны и согласование садовника.':'Карточки совпадают по условиям и группе полива. Это не полная проверка совместимости: учитывайте площадь, высоту и схему посадки.'}
function seasonPage(){if(!account)return heading('Инструменты сезона','Войдите в аккаунт.')+'<button class="btn" onclick="profile()">Войти</button>';if(!seasonData)return '<p>Загружаем инструменты сезона…</p>';const d=seasonData,entries=k=>d.entries.filter(e=>k.includes(e.kind)).map(entryCard).join('')||'<p>Пока нет записей.</p>';let content='';if(seasonTab==='plan')content=`<div class="actions">${se('＋ Событие',"seasonEntry('calendar')")}${se('Продлить аренду','seasonRenew()')}${se('Очередь на грядку',"seasonEntry('waitlist')")}${se('Сменить участок',"seasonEntry('move')")}${se('Объединить управление','seasonGroup()')}${se('Новый цикл посадки','cycleForm()')}</div><section class="panel"><h2>Календарь</h2>${d.calendar.filter(e=>e.at).map(e=>`<div class="event">${esc(e.title)} · №${e.plot_id}<small>${fmt(e.at)}</small></div>`).join('')||'Нет назначенных событий.'}${d.entries.filter(e=>e.kind==='calendar'&&e.status!=='cancelled').map(e=>`<div class="event">${esc(e.title)}<small>${fmt(e.data.at)}</small></div>`).join('')}</section><section class="panel"><h2>Что посадить сейчас?</h2><div id="crop-advisor">${sp()}${sf('month','Месяц','number','min="1" max="12" value="'+(new Date().getMonth()+1)+'"')}<button class="btn" onclick="cropAdvisor()">Подобрать по карточкам фермы</button></div><div id="crop-advice"></div><p class="note">Подбор использует утверждённые управляющим местные условия. Общие принципы <a href="https://extension.umn.edu/vegetable-growing-guides-farmers/crop-and-field-planning-tools-vegetable-farmers" target="_blank" rel="noopener">планирования и повторных посевов</a> не заменяют календарь для Белореченска.</p><h3>Сравнить условия посадок</h3>${d.rules.map(r=>`<label><input type="checkbox" name="compare" value="${r.id}">${esc(r.crop)} · ${esc(r.environment)}</label>`).join('')}<button class="btn light" onclick="compatibilityCheck()">Проверить</button><p id="compatibility-result"></p>${account.role==='admin'?se('Добавить карточку культуры','cropRuleForm()'):''}</section><h2>История и циклы посадок</h2><div class="grid">${d.cycles.map(c=>`<article class="panel"><h3>${esc(c.crop)} · №${c.plot_id}</h3><p>${esc(c.family)} · ${esc(c.conditions)}</p><p>Посадка: ${String(c.starts_on).slice(0,10)} · ${c.approved?'Прогноз подтверждён':'План владельца, не подтверждён'}</p><p>Прогноз обновлён: ${fmt(c.updated_at)}</p><p>Сбор: ${c.expected_from?String(c.expected_from).slice(0,10):'нет прогноза'} — ${c.expected_to?String(c.expected_to).slice(0,10):'нет прогноза'}</p><p>${c.ended_on?'Завершён '+String(c.ended_on).slice(0,10):'Цикл открыт'}</p><div class="actions">${!c.ended_on&&c.owner_id===account.id?se('Частичный сбор',`partialHarvest('${c.id}')`):''}${se('Следующий посев',`cycleForm('${c.id}')`)}${account.role==='admin'?se('Уточнить прогноз',`cycleUpdate('${c.id}')`):''}</div></article>`).join('')||'<p>Циклы ещё не записаны.</p>'}</div><section class="panel"><h2>Группы грядок</h2>${d.groups.map(g=>`<p>${esc(g.name)} · ${g.plots.map(n=>'№'+n).join(', ')}</p>`).join('')||'Нет групп.'}</section><div class="grid">${entries(['waitlist','move'])}</div>`;
if(seasonTab==='care')content=`<div class="actions">${se('Арендовать оборудование',"seasonEntry('equipment_rent')")}${se('Проблема на фото',"seasonEntry('photo_issue')")}${account.role==='admin'?['equipment','weather','sensor','watering','photos','substitute'].map(k=>se('＋ '+seasonLabels[k],`seasonEntry('${k}')`)).join(''):''}</div><p class="note">Показания и погодные предупреждения вводит управляющий с источником и временем. Автоматические интеграции датчиков и метеосервиса не подключены.</p><div class="grid">${entries(['equipment','equipment_rent','weather','sensor','watering','photo_issue','photos','substitute','rework'])}</div><section class="panel"><h2>Приёмка работ</h2>${(opsData?.orders||[]).filter(o=>o.user_id===account.id&&['review','done'].includes(o.status)).map(o=>`<div class="event"><h3>${esc(o.title)} · №${o.plot_id}</h3><p>${esc(o.report||'')}</p>${o.customer_verdict?`<p>${o.customer_verdict==='accepted'?'Принято':'Есть замечание'} · ${esc(o.customer_comment||'')}</p>`:se('Всё хорошо',`customerVerdict('${o.id}','accepted')`)+se('Есть замечание',`customerVerdict('${o.id}','issue')`)}</div>`).join('')||'Нет завершённых работ для приёмки.'}</section>`;
if(seasonTab==='supplies')content=`<div class="actions">${se('＋ Семена или материал','supplyForm()')}</div><div class="grid">${d.supplies.map(s=>`<article class="panel"><h3>${esc(s.name)}</h3><p>${Number(s.balance)} ${esc(s.unit)}</p><p>Годен до: ${s.expires_on?String(s.expires_on).slice(0,10):'не указан'}</p>${se('Учесть расход',`consumeSupply('${s.id}')`)}</article>`).join('')||'<p>Запасов пока нет.</p>'}</div><section class="panel"><h2>Расход материалов</h2>${d.movements.map(m=>`<div class="event">${esc(m.name)} · ${Number(m.quantity)} ${esc(m.unit)} · №${m.plot_id}<small>${fmt(m.created_at)}</small><p>${esc(m.reason)}</p></div>`).join('')||'Расходов пока нет.'}</section>`;
if(seasonTab==='logistics')content=`<div class="actions">${se('Объединить корзины','mergeDeliveries()')}${se('Предзаказать урожай',"seasonEntry('preorder')")}${account.role==='admin'?se('Учесть возвратную тару',"seasonEntry('crate')"):''}</div><section class="panel"><h2>Упаковка доставки</h2>${(lifeData?.deliveries||[]).filter(x=>x.user_id===account.id).map(o=>`<div class="event">${esc(o.recipient)} · ${esc(o.address)}<p>Упаковка: ${({standard:'Обычная',returnable:'Возвратная',gift:'Подарочная'})[o.packaging]} · цена ${o.packaging_quote===null?'согласуется':money(o.packaging_quote)}</p>${o.status==='requested'?se('Выбрать упаковку',`packagingForm('${o.id}')`)+(account.role==='admin'?se('Указать доплату',`packagingQuote('${o.id}')`):''):''}</div>`).join('')||'Нет корзин.'}</section><section class="panel"><h2>Уценка свежих партий</h2>${(lifeData?.myListings||[]).map(l=>`<div class="event">${esc(l.crop)} · ${money(l.price_kopecks)} ${se('Снизить цену',`discountListing('${l.id}')`)}</div>`).join('')||'Нет ваших активных объявлений.'}</section><div class="grid">${entries(['crate','preorder'])}</div>`;
if(seasonTab==='report')content=`<section class="panel"><h2>Итоги по годам</h2><h3>Урожай</h3>${d.summary.harvest.map(h=>`<p>${h.season_year} · ${esc(h.crop)}: ${Number(h.grams)/1000} кг записано, ${Number(h.verified_grams)/1000} кг принято</p>`).join('')||'Урожай пока не записан.'}<h3>Деморасходы</h3>${d.summary.expenses.map(e=>`<p>${e.season_year} · ${({payment:'Работы',subscription:'Подписки',rental:'Аренда',refund:'Возвраты',purchase:'Покупки',sale:'Продажи'})[e.kind]}: ${money(Number(e.amount))}</p>`).join('')}<h3>Полученные корзины</h3>${d.summary.deliveries.map(d=>`<p>${d.season_year} · ${({home:'Домой',gift:'Подарки',charity:'Благотворительность'})[d.kind]}: ${d.count} корзин, ${Number(d.grams)/1000} кг</p>`).join('')||'Подтверждённых доставок пока нет.'}<p>Все суммы — демосредства. Продажи и возвраты показаны отдельно от расходов.</p>${se('Скачать отчёт JSON','exportSeason()')}</section><section class="panel"><h2>Потери урожая</h2>${d.losses.map(l=>`<div class="event">${esc(l.crop)} · ${l.grams/1000} кг<small>${fmt(l.created_at)}</small><p>${esc(l.reason)}</p></div>`).join('')||'Подтверждённых списаний нет.'}</section><h2>Фотографии сезона</h2><div class="grid">${entries(['photos'])}</div>`;
return heading('Сезон под контролем.','Планы, наблюдения, материалы и результаты вашего хозяйства.')+`<div class="room-tabs">${Object.entries({plan:'🌱 План сезона',care:'🔎 Контроль и забота',supplies:'🌾 Семена и материалы',logistics:'🚚 Доставка и продажи',report:'📊 Итоги'}).map(([k,t])=>`<button class="${seasonTab===k?'selected':''}" onclick="seasonTab='${k}';render()">${t}</button>`).join('')}</div>${content}`}
function exportSeason(){const data={generated_at:new Date().toISOString(),summary:seasonData.summary,losses:seasonData.losses};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='farm-off-season.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
const beforeSeasonRender=render;render=function(){beforeSeasonRender();const r=location.hash.slice(1);if(r==='season'){$('#app').innerHTML=seasonPage();$('#crumb').textContent='СЕЗОН'}else if(account&&(r.startsWith('bed-')||r==='settings'||r==='home'&&myPlots().length))$('#app').insertAdjacentHTML('afterbegin','<div class="context-tabs"><a href="#season">🌱 Сезон · календарь · материалы · итоги</a></div>')};addEventListener('hashchange',()=>{if(location.hash==='#season')loadSeason()});const refreshBeforeSeason=refreshCloud;refreshCloud=async function(){await refreshBeforeSeason();if(location.hash==='#season')await loadSeason()};render();

function buyProduce(id){const l=lifeData?.listings.find(x=>x.id===id);if(!l)return;const key=crypto.randomUUID();formAsync('Купить в демомаркете',`<h3>${esc(l.crop)} · ${l.grams/1000} кг · ${money(l.price_kopecks)}</h3><p>Только демосредства. Партия появится в ваших запасах; доставка оформляется отдельно. Физическая передача требует подтверждения фермы.</p><button class="btn">Купить за ${money(l.price_kopecks)} демосредствами</button>`,async()=>seasonAction('buy',{id,key}))}
function packagingQuote(id){seasonForm('Согласовать стоимость упаковки',sf('price','Стоимость, ₽','number','min="0" step="0.01" required'),async f=>seasonAction('packaging-quote',{id,price:Math.round(Number(f.get('price'))*100)}))}
